script:
frappe.ui.form.on('Employee', {
    refresh(frm){
        sumWeekdays(frm);
    },
	custom_monday: function(frm) {
	    sumWeekdays(frm);
	},
	custom_tuesday: function(frm) {
	    sumWeekdays(frm);
	},
	custom_wednesday: function(frm) {
	    sumWeekdays(frm);
	},
	custom_thursday: function(frm) {
	    sumWeekdays(frm);
	},
	custom_friday: function(frm) {
	    sumWeekdays(frm);
	}
})


function sumWeekdays(frm) {
    const sum = frm.doc.custom_monday + frm.doc.custom_tuesday + frm.doc.custom_wednesday + frm.doc.custom_thursday + frm.doc.custom_friday;
    frm.set_value("custom_weekly_sum",sum);
}

frappe.listview_settings['Contact'] = {
    refresh: function(listview) {
        listview.page.set_primary_action(__('+ Add Contact'), function() {
            add_contact();
        });
    }
};

function add_contact() {
    frappe.db.get_doc('DocType', 'Contact').then(doc => {
        let fields = [
            {
                label: __('First Name'),
                fieldname: 'first_name',
                fieldtype: 'Data',
                reqd: 0
            },
            {
                label: __('Last Name'),
                fieldname: 'last_name',
                fieldtype: 'Data',
                reqd: 0
            },
            {
                label: __('E-Mail Address'),
                fieldname: 'email',
                fieldtype: 'Data',
                options: 'Contact Email',
                reqd: 0
            },
            {
                label: __('Phone Number'),
                fieldname: 'phone',
                fieldtype: 'Data',
                options: 'Contact Phone',
                reqd: 0
            },
            {
                label: __('Company Name'),
                fieldname: 'company_name',
                fieldtype: 'Data',
                reqd: 0
            },
            {
                label: __('Address'),
                fieldname: 'address',
                fieldtype: 'Link',
                options: 'Address',
                reqd: 0
            },
            {
                label: __('Status'),
                fieldname: 'status',
                fieldtype: 'Select',
                options: ['Passive', 'Open', 'Replied'],
                reqd: 0
            },
            {
                label: __('Key Account'),
                fieldname: 'key_account',
                fieldtype: 'Link',
                options: 'User',
                reqd: 0
            }
        ];

        var dialog = new frappe.ui.Dialog({
            title: __('New Contact'),
            fields: fields,
            primary_action: function() {
                var values = dialog.get_values();

                if (values) {
                    let contact_doc = {                                
                    doctype: 'Contact',
                    first_name: values.first_name,
                    last_name: values.last_name,
                    status: values.status,
                    company_name: values.company_name,
                    custom_key_account: values.key_account,
                    }
                    if (values.email) {
                        contact_doc.email_ids = [{email_id: values.email, is_primary: 1}]
                    }
                    if (values.phone) {
                        contact_doc.phone_nos = [{phone: values.phone, is_primary_mobile_no: 0, is_primary_phone_no: 0}]
                    }
                    frappe.call({
                        method: 'frappe.client.insert',
                        args: {
                            doc: contact_doc
                        },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.msgprint(__('Contact Saved!'));
                                dialog.hide();
                            } else {
                                frappe.msgprint(__('Failed to save contact.'));
                            }
                        }
                    });
                }
            },
            secondary_action: function() {
                dialog.hide();
                frappe.set_route("Form", 'Contact', 'new-contact');
            },
            primary_action_label: __('Save'),
            secondary_action_label: __('Edit Full Form')
        });

        dialog.show();
    });
}
